#!/usr/bin/env python
"""
03_prediction_CellFM.py - generate and format CellFM perturbation predictions

This release-facing entry point integrates all-gene prediction and benchmarking
output formatting for CellFM.
"""

import argparse
import sys

STAGE_SOURCES = {'predict': '"""\n03_prediction_CellFM.py - Prediction with CellFM+GEARS Model\n\nThis script generates predictions for perturbations using a trained CellFM+GEARS model.\nIt follows the approach from the reference scGPT prediction code but adapted for our\ncell-level embedding model.\n\nUsage:\n    python 03_prediction_CellFM.py \\\n        --model_dir /path/to/results/cellfm/seed_3 \\\n        --data_dir /path/to/gears_data \\\n        --data_name nocap_perturbation \\\n        --emb_path /path/to/embeddings.npy \\\n        --output_dir /path/to/predictions \\\n        --seed 3 \\\n        --device cuda:0\n"""\n\nimport os\nimport sys\nimport argparse\nimport numpy as np\nimport torch\nimport pickle\nfrom tqdm import tqdm\nfrom datetime import datetime\nimport scanpy as sc\nimport anndata as ad\nfrom torch_geometric.loader import DataLoader\n\n# Add parent directory to path\nCODES_DIR = os.path.dirname(os.path.abspath(__file__))\nROOT_DIR = os.path.dirname(CODES_DIR)\nsys.path.insert(0, ROOT_DIR)\nsys.path.insert(0, CODES_DIR)\n\nfrom gears import PertData\nfrom gears.utils import create_cell_graph_dataset_for_prediction\nfrom cellfm_gears_model import GEARS_Model_CellEmb, load_cell_embeddings\n\n\ndef parse_args():\n    parser = argparse.ArgumentParser(description=\'Predict with CellFM+GEARS Model\')\n\n    # Model and data paths\n    parser.add_argument(\'--model_dir\', type=str, required=True,\n                        help=\'Directory containing trained model (with best_model.pt)\')\n    parser.add_argument(\'--data_dir\', type=str, required=True,\n                        help=\'Directory containing GEARS data\')\n    parser.add_argument(\'--data_name\', type=str, required=True,\n                        help=\'Dataset name (e.g., nocap_perturbation)\')\n    parser.add_argument(\'--emb_path\', type=str, required=True,\n                        help=\'Path to cell-level embeddings (.npy file)\')\n    parser.add_argument(\'--output_dir\', type=str, required=True,\n                        help=\'Output directory for predictions\')\n\n    # Model parameters (should match training)\n    parser.add_argument(\'--hidden_size\', type=int, default=512,\n                        help=\'Hidden size (default: 512)\')\n    parser.add_argument(\'--max_cells\', type=int, default=600,\n                        help=\'Maximum number of cells from embeddings (default: 600)\')\n\n    # Split parameters (should match training)\n    parser.add_argument(\'--seed\', type=int, default=3,\n                        help=\'Random seed for data split (default: 3)\')\n    parser.add_argument(\'--split\', type=str, default=\'simulation\',\n                        help=\'Split type (default: simulation)\')\n    parser.add_argument(\'--train_gene_set_size\', type=float, default=0.75,\n                        help=\'Train gene set size (default: 0.75)\')\n\n    # Prediction parameters\n    parser.add_argument(\'--num_ctrl_samples\', type=int, default=100,\n                        help=\'Number of control samples per prediction (default: 100)\')\n    parser.add_argument(\'--batch_size\', type=int, default=32,\n                        help=\'Batch size for prediction (default: 32)\')\n\n    # Device\n    parser.add_argument(\'--device\', type=str, default=\'cuda:0\',\n                        help=\'Device to use (default: cuda:0)\')\n\n    # Options\n    parser.add_argument(\'--save_h5ad\', action=\'store_true\',\n                        help=\'Save predictions as h5ad files per perturbation\')\n    parser.add_argument(\'--test_only\', action=\'store_true\',\n                        help=\'Only predict for test set perturbations\')\n    parser.add_argument(\'--all_genes\', action=\'store_true\',\n                        help=\'Predict for ALL genes (19424 perturbations)\')\n\n    return parser.parse_args()\n\n\ndef setup_gears_args(pert_data, hidden_size, device, data_dir, data_name):\n    """Setup arguments for GEARS model initialization (same as training)."""\n    import pandas as pd\n    import pickle as pkl\n\n    dataset_path = os.path.join(data_dir, data_name)\n    print(f"  Dataset path: {dataset_path}")\n\n    # Get perturbation names from gene2go.pkl\n    gene2go_path = os.path.join(data_dir, \'gene2go.pkl\')\n    print(f"  Loading perturbation names from {gene2go_path}...")\n    with open(gene2go_path, \'rb\') as f:\n        gene2go = pkl.load(f)\n    pert_names = list(gene2go.keys())\n    num_perts = len(pert_names)\n    print(f"  Number of perturbations: {num_perts:,}")\n\n    # Load pre-computed GO graph\n    go_path = os.path.join(dataset_path, \'go.csv\')\n    if os.path.exists(go_path):\n        print(f"  Loading pre-computed GO graph from {go_path}...")\n        go_df = pd.read_csv(go_path)\n        go_df = go_df.dropna()\n        print(f"  GO graph edges: {len(go_df):,}")\n\n        gene_to_idx = {gene: idx for idx, gene in enumerate(pert_names)}\n\n        valid_edges = []\n        valid_weights = []\n        skipped = 0\n        for i, row in go_df.iterrows():\n            src, tgt = row[\'source\'], row[\'target\']\n            if src in gene_to_idx and tgt in gene_to_idx:\n                valid_edges.append([gene_to_idx[src], gene_to_idx[tgt]])\n                valid_weights.append(row[\'importance\'])\n            else:\n                skipped += 1\n\n        if skipped > 0:\n            print(f"  Skipped {skipped:,} edges (genes not in gene2go.pkl)")\n        print(f"  Valid GO graph edges: {len(valid_edges):,}")\n\n        if len(valid_edges) > 0:\n            G_go = torch.LongTensor(valid_edges).T\n            G_go_weight = torch.FloatTensor(valid_weights)\n        else:\n            G_go = torch.LongTensor([[i, i] for i in range(num_perts)]).T\n            G_go_weight = torch.ones(num_perts)\n    else:\n        print(f"  go.csv not found, using self-loops...")\n        G_go = torch.LongTensor([[i, i] for i in range(num_perts)]).T\n        G_go_weight = torch.ones(num_perts)\n\n    # Gene co-expression graph\n    num_genes = pert_data.adata.n_vars\n    G_coexpress = torch.LongTensor([[i, i] for i in range(num_genes)]).T\n    G_coexpress_weight = torch.ones(num_genes)\n\n    args = {\n        \'num_genes\': num_genes,\n        \'num_perts\': len(pert_names),\n        \'hidden_size\': hidden_size,\n        \'uncertainty\': False,\n        \'num_go_gnn_layers\': 2,\n        \'decoder_hidden_size\': hidden_size,\n        \'num_gene_gnn_layers\': 2,\n        \'no_perturb\': False,\n        \'cell_fitness_pred\': False,\n        \'G_go\': G_go,\n        \'G_go_weight\': G_go_weight,\n        \'G_coexpress\': G_coexpress,\n        \'G_coexpress_weight\': G_coexpress_weight,\n        \'device\': device,\n        \'model_type\': \'emb\',\n    }\n\n    return args\n\n\ndef predict(model, pert_list, ctrl_adata, gene_names, device,\n            num_samples=30, batch_size=32):\n    """\n    Generate predictions for a list of perturbations.\n\n    Args:\n        model: Trained GEARS model\n        pert_list: List of perturbation gene names (each as a list, e.g., [[\'GENE1\'], [\'GENE2\']])\n        ctrl_adata: AnnData object containing control cells\n        gene_names: List of gene names\n        device: torch device\n        num_samples: Number of control cells to sample per perturbation\n        batch_size: Batch size for prediction\n\n    Returns:\n        dict: Mapping from perturbation name to predicted expression (n_samples, n_genes)\n    """\n    model.eval()\n    results = {}\n\n    for pert in tqdm(pert_list, desc="Predicting perturbations"):\n        # pert is a list like [\'GENE1\'] for single perturbations\n        pert_name = \'_\'.join(pert) if isinstance(pert, list) else pert\n\n        try:\n            # Create cell graphs for prediction\n            cell_graphs = create_cell_graph_dataset_for_prediction(\n                pert if isinstance(pert, list) else [pert],\n                ctrl_adata,\n                gene_names,\n                device,\n                num_samples=num_samples\n            )\n\n            # Create data loader\n            loader = DataLoader(cell_graphs, batch_size=batch_size, shuffle=False)\n\n            # Collect predictions\n            preds = []\n            with torch.no_grad():\n                for batch in loader:\n                    batch = batch.to(device)\n                    pred = model(batch)\n                    preds.append(pred.detach().cpu().numpy())\n\n            # Concatenate all predictions\n            preds = np.concatenate(preds, axis=0)\n            results[pert_name] = preds\n\n        except Exception as e:\n            print(f"  Warning: Failed to predict for {pert_name}: {e}")\n            continue\n\n    return results\n\n\ndef main():\n    args = parse_args()\n\n    print("=" * 70)\n    print("CellFM+GEARS Prediction")\n    print("=" * 70)\n    print(f"Model directory: {args.model_dir}")\n    print(f"Data directory: {args.data_dir}")\n    print(f"Dataset: {args.data_name}")\n    print(f"Embedding path: {args.emb_path}")\n    print(f"Output directory: {args.output_dir}")\n    print(f"Seed: {args.seed}")\n    print(f"Device: {args.device}")\n    print("=" * 70)\n\n    # Create output directory\n    os.makedirs(args.output_dir, exist_ok=True)\n\n    # Set random seeds\n    np.random.seed(args.seed)\n    torch.manual_seed(args.seed)\n    if torch.cuda.is_available():\n        torch.cuda.manual_seed(args.seed)\n\n    # Setup device\n    device = torch.device(args.device if torch.cuda.is_available() else \'cpu\')\n    print(f"\\nUsing device: {device}")\n\n    # Load perturbation data with same split as training\n    print("\\n[1/5] Loading perturbation data...")\n    pert_data = PertData(args.data_dir)\n    pert_data.load(data_path=os.path.join(args.data_dir, args.data_name))\n    pert_data.prepare_split(\n        split=args.split,\n        seed=args.seed,\n        train_gene_set_size=args.train_gene_set_size\n    )\n\n    print(f"  Total genes: {pert_data.adata.n_vars}")\n    print(f"  Total cells: {pert_data.adata.n_obs}")\n\n    # Get gene names\n    gene_names = list(pert_data.adata.var_names)\n\n    # Get control cells\n    ctrl_adata = pert_data.adata[pert_data.adata.obs[\'condition\'] == \'ctrl\']\n    print(f"  Control cells: {ctrl_adata.n_obs}")\n\n    # Load cell-level embeddings\n    print("\\n[2/5] Loading cell-level embeddings...")\n    ctrl_emb = load_cell_embeddings(args.emb_path, device=device, max_cells=args.max_cells)\n\n    # Setup model arguments\n    print("\\n[3/5] Initializing model...")\n    model_args = setup_gears_args(pert_data, args.hidden_size, device,\n                                   args.data_dir, args.data_name)\n\n    # Create model\n    model = GEARS_Model_CellEmb(model_args, ctrl_emb=ctrl_emb)\n    model = model.to(device)\n\n    # Load trained weights\n    model_path = os.path.join(args.model_dir, \'best_model.pt\')\n    print(f"  Loading model from {model_path}...")\n    checkpoint = torch.load(model_path, map_location=\'cpu\')\n    model.load_state_dict(checkpoint)\n    del checkpoint\n    model = model.to(device)\n    print("  Model loaded successfully!")\n\n    # Count parameters\n    total_params = sum(p.numel() for p in model.parameters())\n    print(f"  Total parameters: {total_params:,}")\n\n    # Get perturbation list for prediction\n    print("\\n[4/5] Preparing perturbation list...")\n\n    if args.all_genes:\n        # Predict for ALL genes in the dataset (19424 single-gene perturbations)\n        # This creates one h5ad file per gene\n        pert_list = [[gene] for gene in gene_names]\n        print(f"  Mode: ALL GENES - predicting for all {len(pert_list)} genes")\n    elif args.test_only:\n        # Get test perturbations from the split\n        split_path = os.path.join(args.data_dir, args.data_name, \'splits\',\n                                  f\'{args.data_name}_{args.split}_{args.seed}_{args.train_gene_set_size}.pkl\')\n        if os.path.exists(split_path):\n            with open(split_path, \'rb\') as f:\n                split_data = pickle.load(f)\n            test_perts = split_data.get(\'test\', [])\n            print(f"  Found {len(test_perts)} test perturbations from split file")\n        else:\n            # Fallback: get unique perturbations from test set\n            test_perts = list(pert_data.adata.obs[\'condition\'].unique())\n            test_perts = [p for p in test_perts if p != \'ctrl\']\n            print(f"  Found {len(test_perts)} unique perturbations")\n        # Convert to list format expected by create_cell_graph_dataset_for_prediction\n        # Format: "GENE+ctrl" for single, "GENE1+GENE2+ctrl" for combo\n        # Need to remove "+ctrl" suffix and convert to list of genes\n        pert_list = []\n        for p in test_perts:\n            if \'+ctrl\' in p:\n                # Remove +ctrl suffix and split remaining by +\n                genes = p.replace(\'+ctrl\', \'\').split(\'+\')\n                pert_list.append(genes)\n            else:\n                # Single gene without ctrl suffix\n                pert_list.append([p])\n    else:\n        # Get all perturbations present in the dataset\n        all_perts = list(pert_data.adata.obs[\'condition\'].unique())\n        all_perts = [p for p in all_perts if p != \'ctrl\']\n        # Convert to list format expected by create_cell_graph_dataset_for_prediction\n        pert_list = []\n        for p in all_perts:\n            if \'+ctrl\' in p:\n                genes = p.replace(\'+ctrl\', \'\').split(\'+\')\n                pert_list.append(genes)\n            else:\n                pert_list.append([p])\n\n    print(f"  Predicting for {len(pert_list)} perturbations")\n\n    # Run prediction\n    print("\\n[5/5] Running predictions...")\n    predictions = predict(\n        model=model,\n        pert_list=pert_list,\n        ctrl_adata=ctrl_adata,\n        gene_names=gene_names,\n        device=device,\n        num_samples=args.num_ctrl_samples,\n        batch_size=args.batch_size\n    )\n\n    print(f"  Successfully predicted {len(predictions)} perturbations")\n\n    # Save predictions\n    print("\\nSaving predictions...")\n\n    # Save as pickle (all predictions)\n    pred_path = os.path.join(args.output_dir, \'predictions.pkl\')\n    with open(pred_path, \'wb\') as f:\n        pickle.dump(predictions, f)\n    print(f"  Saved all predictions to {pred_path}")\n\n    # Save as numpy arrays\n    pred_np_path = os.path.join(args.output_dir, \'predictions_arrays.npz\')\n    np.savez(pred_np_path, **predictions)\n    print(f"  Saved predictions as numpy arrays to {pred_np_path}")\n\n    # Optionally save as h5ad files per gene\n    if args.save_h5ad:\n        h5ad_dir = os.path.join(args.output_dir, \'h5ad\')\n        os.makedirs(h5ad_dir, exist_ok=True)\n        print(f"  Saving h5ad files to {h5ad_dir}...")\n\n        for pert_name, pred in tqdm(predictions.items(), desc="Saving h5ad"):\n            # Create AnnData object\n            adata = ad.AnnData(X=pred)\n            adata.var_names = gene_names\n            adata.obs[\'condition\'] = pert_name\n\n            # Save\n            h5ad_path = os.path.join(h5ad_dir, f\'{pert_name}.h5ad\')\n            adata.write(h5ad_path)\n\n    # Save metadata\n    metadata = {\n        \'model_dir\': args.model_dir,\n        \'data_dir\': args.data_dir,\n        \'data_name\': args.data_name,\n        \'seed\': args.seed,\n        \'num_ctrl_samples\': args.num_ctrl_samples,\n        \'num_predictions\': len(predictions),\n        \'gene_names\': gene_names,\n        \'timestamp\': datetime.now().isoformat()\n    }\n    meta_path = os.path.join(args.output_dir, \'prediction_metadata.pkl\')\n    with open(meta_path, \'wb\') as f:\n        pickle.dump(metadata, f)\n\n    print("\\n" + "=" * 70)\n    print("Prediction Complete!")\n    print("=" * 70)\n    print(f"Predictions saved to: {args.output_dir}")\n    print(f"  - predictions.pkl: All predictions as dict")\n    print(f"  - predictions_arrays.npz: Numpy arrays")\n    if args.save_h5ad:\n        print(f"  - h5ad/: Individual h5ad files per perturbation")\n    print(f"  - prediction_metadata.pkl: Metadata")\n\n\nif __name__ == \'__main__\':\n    main()\n', 'format': '"""\n04_final_output.py - Convert CellFM+GEARS predictions to reference pickle format\n\nThis script converts the predictions from 04_predict.py into the exact same format\nas the reference file (Telen-NOCAP.pickle).\n\nReference format:\n    - pandas DataFrame of shape (19424, 19424)\n    - Index (rows): Gene names in alphabetical order (\'A1BG\', \'A1CF\', ..., \'ZZZ3\')\n    - Columns: Perturbation names with \'_perturbed\' suffix (specific ordering from reference)\n    - Values: float32, averaged gene expression predictions across control samples\n    - Row i, Column j: Expression of gene i when gene j is perturbed\n\nOur predictions format:\n    - predictions.pkl: Dict mapping gene_name -> (num_ctrl_samples, 19424) arrays\n    - prediction_metadata.pkl: Contains gene_names list\n\nUsage:\n    python 04_final_output.py \\\n        --predictions_dir /path/to/predictions/cellfm/seed_3_allgenes \\\n        --reference_pickle /path/to/ref_code/Telen-NOCAP.pickle \\\n        --output_path /path/to/output/CellFM_predictions.pickle\n"""\n\nimport os\nimport sys\nimport argparse\nimport pickle\nimport numpy as np\nimport pandas as pd\nfrom tqdm import tqdm\n\n\ndef parse_args():\n    parser = argparse.ArgumentParser(description=\'Convert predictions to reference format\')\n\n    parser.add_argument(\'--predictions_dir\', type=str, required=True,\n                        help=\'Directory containing predictions.pkl and prediction_metadata.pkl\')\n    parser.add_argument(\'--reference_pickle\', type=str, required=True,\n                        help=\'Path to reference pickle file (Telen-NOCAP.pickle)\')\n    parser.add_argument(\'--output_path\', type=str, required=True,\n                        help=\'Output path for the formatted pickle file\')\n\n    return parser.parse_args()\n\n\ndef main():\n    args = parse_args()\n\n    print("=" * 70)\n    print("Convert CellFM+GEARS Predictions to Reference Format")\n    print("=" * 70)\n    print(f"Predictions directory: {args.predictions_dir}")\n    print(f"Reference pickle: {args.reference_pickle}")\n    print(f"Output path: {args.output_path}")\n    print("=" * 70)\n\n    # Load reference to get exact format\n    print("\\n[1/4] Loading reference pickle for format...")\n    with open(args.reference_pickle, \'rb\') as f:\n        ref_df = pickle.load(f)\n\n    print(f"  Reference shape: {ref_df.shape}")\n    print(f"  Reference index (rows): {len(ref_df.index)} genes")\n    print(f"  Reference columns: {len(ref_df.columns)} perturbations")\n    print(f"  Reference dtype: {ref_df.values.dtype}")\n\n    # Get gene order (index = rows)\n    gene_names = list(ref_df.index)\n\n    # Get perturbation order (columns) - extract gene names without \'_perturbed\' suffix\n    perturbation_order = [c.replace(\'_perturbed\', \'\') for c in ref_df.columns]\n\n    # Clear reference from memory\n    del ref_df\n\n    # Load predictions\n    print("\\n[2/4] Loading predictions...")\n    predictions_path = os.path.join(args.predictions_dir, \'predictions.pkl\')\n    metadata_path = os.path.join(args.predictions_dir, \'prediction_metadata.pkl\')\n\n    with open(predictions_path, \'rb\') as f:\n        predictions = pickle.load(f)\n    print(f"  Loaded {len(predictions)} perturbation predictions")\n\n    with open(metadata_path, \'rb\') as f:\n        metadata = pickle.load(f)\n    our_gene_names = metadata[\'gene_names\']\n    print(f"  Our gene order: {len(our_gene_names)} genes")\n\n    # Verify gene names match\n    if set(our_gene_names) != set(gene_names):\n        print("  WARNING: Gene names don\'t match!")\n        print(f"    Missing in ours: {set(gene_names) - set(our_gene_names)}")\n        print(f"    Extra in ours: {set(our_gene_names) - set(gene_names)}")\n    else:\n        print("  Gene names match reference!")\n\n    # Check if our gene order matches reference index order\n    if our_gene_names == gene_names:\n        print("  Gene order matches reference index!")\n    else:\n        print("  Gene order differs from reference - will reorder rows")\n\n    # Create gene index mapping for our predictions\n    our_gene_to_idx = {gene: idx for idx, gene in enumerate(our_gene_names)}\n\n    # Build the matrix\n    print("\\n[3/4] Building prediction matrix...")\n    print(f"  Target shape: ({len(gene_names)}, {len(perturbation_order)})")\n\n    # Initialize matrix with NaN\n    pred_matrix = np.full((len(gene_names), len(perturbation_order)), np.nan, dtype=np.float32)\n\n    # Fill in predictions - iterate over perturbations (columns)\n    missing_perts = []\n    for col_idx, pert_gene in enumerate(tqdm(perturbation_order, desc="Processing perturbations")):\n        if pert_gene in predictions:\n            # predictions[pert_gene] has shape (num_ctrl_samples, num_genes)\n            # Average across control samples to get (num_genes,)\n            avg_pred = predictions[pert_gene].mean(axis=0)\n\n            # Map to correct row order (reference gene order)\n            for row_idx, gene in enumerate(gene_names):\n                if gene in our_gene_to_idx:\n                    src_idx = our_gene_to_idx[gene]\n                    pred_matrix[row_idx, col_idx] = avg_pred[src_idx]\n        else:\n            missing_perts.append(pert_gene)\n\n    if missing_perts:\n        print(f"  WARNING: {len(missing_perts)} perturbations missing from predictions")\n        if len(missing_perts) <= 10:\n            print(f"    Missing: {missing_perts}")\n        else:\n            print(f"    First 10 missing: {missing_perts[:10]}")\n\n    # Check for NaN\n    nan_count = np.isnan(pred_matrix).sum()\n    if nan_count > 0:\n        print(f"  WARNING: {nan_count} NaN values in matrix ({nan_count / pred_matrix.size * 100:.2f}%)")\n    else:\n        print("  No NaN values in matrix!")\n\n    # Create DataFrame with correct index and columns\n    print("\\n[4/4] Creating DataFrame and saving...")\n    column_names = [f"{gene}_perturbed" for gene in perturbation_order]\n\n    output_df = pd.DataFrame(\n        pred_matrix,\n        index=gene_names,\n        columns=column_names\n    )\n\n    print(f"  Output shape: {output_df.shape}")\n    print(f"  Output dtype: {output_df.values.dtype}")\n    print(f"  Output index (first 5): {list(output_df.index[:5])}")\n    print(f"  Output columns (first 5): {list(output_df.columns[:5])}")\n\n    # Statistics\n    print(f"\\n  Statistics:")\n    print(f"    Min: {output_df.values.min():.6f}")\n    print(f"    Max: {output_df.values.max():.6f}")\n    print(f"    Mean: {output_df.values.mean():.6f}")\n    print(f"    Std: {output_df.values.std():.6f}")\n\n    # Save\n    os.makedirs(os.path.dirname(args.output_path), exist_ok=True)\n    with open(args.output_path, \'wb\') as f:\n        pickle.dump(output_df, f)\n\n    file_size = os.path.getsize(args.output_path) / (1024**3)\n    print(f"\\n  Saved to: {args.output_path}")\n    print(f"  File size: {file_size:.2f} GB")\n\n    print("\\n" + "=" * 70)\n    print("Conversion Complete!")\n    print("=" * 70)\n\n\nif __name__ == \'__main__\':\n    main()\n'}


def run_embedded_stage(stage_name, argv):
    source = STAGE_SOURCES[stage_name]
    filename = f"<CellFM {stage_name} stage>"
    namespace = {'__name__': '__embedded_stage__', '__file__': filename}
    old_argv = sys.argv[:]
    try:
        sys.argv = [filename] + list(argv)
        exec(compile(source, filename, 'exec'), namespace)
        namespace['main']()
    finally:
        sys.argv = old_argv


def main():
    parser = argparse.ArgumentParser(description='Generate and format CellFM perturbation predictions')
    parser.add_argument('--skip_prediction', action='store_true')
    parser.add_argument('--skip_format', action='store_true')
    parser.add_argument('--model_dir', required=True)
    parser.add_argument('--data_dir', required=True)
    parser.add_argument('--data_name', required=True)
    parser.add_argument('--emb_path', required=True)
    parser.add_argument('--predictions_dir', required=True)
    parser.add_argument('--reference_pickle', required=True)
    parser.add_argument('--output_path', required=True)
    parser.add_argument('--hidden_size', type=int, default=512)
    parser.add_argument('--max_cells', type=int, default=600)
    parser.add_argument('--seed', type=int, default=3)
    parser.add_argument('--num_ctrl_samples', type=int, default=100)
    parser.add_argument('--batch_size', type=int, default=32)
    parser.add_argument('--device', default='cuda:0')
    parser.add_argument('--gene_start', type=int, default=None)
    parser.add_argument('--gene_end', type=int, default=None)
    parser.add_argument('--all_genes', action='store_true')
    parser.add_argument('--save_h5ad', action='store_true')
    args = parser.parse_args()

    if not args.skip_prediction:
        pred_args = [
            '--model_dir', args.model_dir,
            '--data_dir', args.data_dir,
            '--data_name', args.data_name,
            '--emb_path', args.emb_path,
            '--output_dir', args.predictions_dir,
            '--hidden_size', str(args.hidden_size),
            '--max_cells', str(args.max_cells),
            '--seed', str(args.seed),
            '--num_ctrl_samples', str(args.num_ctrl_samples),
            '--batch_size', str(args.batch_size),
            '--device', args.device,
        ]
        if args.gene_start is not None:
            pred_args += ['--gene_start', str(args.gene_start)]
        if args.gene_end is not None:
            pred_args += ['--gene_end', str(args.gene_end)]
        if args.all_genes:
            pred_args.append('--all_genes')
        if args.save_h5ad:
            pred_args.append('--save_h5ad')
        run_embedded_stage('predict', pred_args)

    if not args.skip_format:
        run_embedded_stage('format', [
            '--predictions_dir', args.predictions_dir,
            '--reference_pickle', args.reference_pickle,
            '--output_path', args.output_path,
        ])


if __name__ == '__main__':
    main()
